void bucket_add_partition_point(std::vector<float>& hash_points, float point) {
    if (hash_points.empty() || point > hash_points.back()) {
        hash_points.push_back(point);
    } else if (point < hash_points.front()) {
        hash_points.insert(hash_points.begin(), point);
    } else {
        auto it = std::lower_bound(hash_points.begin(), hash_points.end(), point);
        hash_points.insert(it, point);
    }
}

